using System.Diagnostics;
using System.IO;
namespace VisualNovelResourceTool.App;
public static class UnrpycService
{
 public static async Task<(int Files,string Log)> DecompileAsync(string source,string output,CancellationToken token){var files=Directory.EnumerateFiles(source,"*.rpyc",SearchOption.AllDirectories).ToArray();if(files.Length==0)throw new InvalidOperationException("所选目录中没有 .rpyc 文件。");Directory.CreateDirectory(output);foreach(var file in files){var target=Path.Combine(output,Path.GetRelativePath(source,file));Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(file,target,true);}var python=FindPython(source)??throw new InvalidOperationException("没有找到可用的 Python 3；请选择 Ren’Py 游戏根目录、game 目录或其解包结果。");var script=Path.Combine(AppContext.BaseDirectory,"third_party","unrpyc","unrpyc.py");if(!File.Exists(script))throw new FileNotFoundException("发布包中缺少 unrpyc。",script);var psi=new ProcessStartInfo(python){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=Path.GetDirectoryName(script)!};psi.ArgumentList.Add(script);psi.ArgumentList.Add(output);psi.ArgumentList.Add("--try-harder");using var p=Process.Start(psi)!;var stdout=p.StandardOutput.ReadToEndAsync(token);var stderr=p.StandardError.ReadToEndAsync(token);await p.WaitForExitAsync(token);var log=await stdout+await stderr;if(p.ExitCode!=0)throw new InvalidOperationException($"unrpyc 返回错误 {p.ExitCode}：\n{log}");return(files.Length,log);}
 private static string? FindPython(string path){var current=new DirectoryInfo(path);while(current is not null){var lib=Path.Combine(current.FullName,"lib");if(Directory.Exists(lib)){var hit=Directory.EnumerateFiles(lib,"python.exe",SearchOption.AllDirectories).FirstOrDefault();if(hit is not null)return hit;}current=current.Parent;}foreach(var folder in (Environment.GetEnvironmentVariable("PATH")??"").Split(Path.PathSeparator)){var candidate=Path.Combine(folder.Trim(),"python.exe");if(File.Exists(candidate))return candidate;}return null;}
}
